#include <Arduino.h>
#include <Servo.h>
const int SHCP_PIN = A2;  
const int STCP_PIN = A1;  
const int DS_PIN = A0;    
const int POT1_PIN = A3;  
const int POT2_PIN = A4;  
const int SERVO1_PIN = 2; 
const int SERVO2_PIN = 3; 
Servo servo1;
Servo servo2;
const byte segmentCodes[] = {
  0b11000000, 
  0b11111001, 
  0b10100100, 
  0b10110000, 
  0b10011001, 
  0b10010010, 
  0b10000010, 
  0b11111000, 
  0b10000000, 
  0b10010000  
};

void setup();
void loop();
void displayNumber(int number);
void setup() {
  pinMode(SHCP_PIN, OUTPUT);
  pinMode(STCP_PIN, OUTPUT);
  pinMode(DS_PIN, OUTPUT);
  servo1.attach(SERVO1_PIN);
  servo2.attach(SERVO2_PIN);
  displayNumber(0); 
  servo1.write(0);
  servo2.write(0);
}
void loop() {
  int pot1Value = analogRead(POT1_PIN);
  int pot2Value = analogRead(POT2_PIN);
  int angle1 = map(pot1Value, 0, 1023, 0, 99);
  int angle2 = map(pot2Value, 0, 1023, 0, 99);
  servo1.write(angle1);
  servo2.write(angle2);
  displayNumber(angle1); 
}
void displayNumber(int number) {
  int tens = number / 10;
  int ones = number % 10;
  byte tensCode = segmentCodes[tens];
  byte onesCode = segmentCodes[ones];
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, onesCode);
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, tensCode);
  digitalWrite(STCP_PIN, HIGH);
  digitalWrite(STCP_PIN, LOW);
}
